async function annulerAvant() {
  const controleur = new AbortController();
  controleur.abort();
  try {
    await fetch("/api-pedagogique/v1/lent", {signal:controleur.signal});
    return "Reçu";
  } catch (erreur) {
    if (erreur.name === "AbortError") { return "Annulé"; }
    throw erreur;
  }
}

